import{_ as u,a0 as p,w as e,s as l,ao as a,I as i,x as n,a1 as o,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"將手機作為你的 Linux 桌面的攝像頭和麥克風 | LCTT x X-CMD","titleTemplate":false,"description":"將手機作為你的 Linux 桌面的攝像頭和麥克風 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"將手機作為你的 Linux 桌面的攝像頭和麥克風 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"將手機作為你的 Linux 桌面的攝像頭和麥克風 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230828 Using Your Phone as Camera and Mic in Ubuntu Linux","title":"將手機作為你的 Linux 桌面的攝像頭和麥克風","tag":"202309","desc":""},"relativePath":"202309/20230828 Using Your Phone as Camera and Mic in Ubuntu Linux.md","filePath":"[post].md"}'),d={name:"202309/20230828 Using Your Phone as Camera and Mic in Ubuntu Linux.md"};function b(m,t,g,f,h,k){const s=p("Link");return e(),l("div",null,[t[33]||(t[33]=a('<h1 id="將手機作為你的-linux-桌面的攝像頭和麥克風" tabindex="-1">將手機作為你的 Linux 桌面的攝像頭和麥克風 <a class="header-anchor" href="#將手機作為你的-linux-桌面的攝像頭和麥克風" aria-label="Permalink to “將手機作為你的 Linux 桌面的攝像頭和麥克風”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/07/155221kxjpb8j8j998xj50.jpg" alt=""></p><blockquote><p>當你的桌面系統缺乏網絡攝像頭和專用麥克風時，你可以考慮使用智能手機。這裏將教你如何在 Ubuntu Linux 中完成這個設置。</p></blockquote><p>我和許多 Linux 用户一樣，使用的是台式機。相較於筆記本電腦，並沒有預裝攝像頭和麥克風。</p><p>若要獲得與現代智能手機相媲美的畫質，你可能需要購買一款高端的網絡攝像頭。</p><p>在此教程中，我將逐步指導你如何將你的手機用作麥克風和攝像頭，這將非常適用於在線會議場景。</p><h3 id="ubuntu-下使用手機的攝像頭和麥克風" tabindex="-1">Ubuntu 下使用手機的攝像頭和麥克風 <a class="header-anchor" href="#ubuntu-下使用手機的攝像頭和麥克風" aria-label="Permalink to “Ubuntu 下使用手機的攝像頭和麥克風”">​</a></h3>',7)),i("blockquote",null,[i("p",null,[t[1]||(t[1]=n("🚧 本教程採用第三方網站 ",-1)),o(s,{href:"https://vdo.ninja/"},{default:r(()=>[...t[0]||(t[0]=[n("https://vdo.ninja/",-1)])]),_:1}),t[2]||(t[2]=n(" 來託管音頻和視頻，因此，這並不是一項完全的開源方案。",-1))])]),t[34]||(t[34]=a('<p>我將指引你完成以下步驟：</p><ul><li>安裝 OBS （如果你還未安裝）</li><li>通過 <code>vdo.ninja</code> 生成邀請鏈接</li><li>設置虛擬音頻線纜（用於音頻輸出）</li><li>配置 OBS 以便從 <code>vdo.ninja</code> 重定向音視頻流</li></ul><p>首先，我們來看第一步。</p><blockquote><p>📋 雖然本教程是在 Ubuntu 系統下完成的，但我相信，這些同樣可以在其他 Linux 發行版上實現。你只需為你的發行版安裝所需的包即可。你可以自行嘗試，看看效果如何。</p></blockquote><h4 id="_1、在-ubuntu-中安裝-obs" tabindex="-1">1、在 Ubuntu 中安裝 OBS <a class="header-anchor" href="#_1、在-ubuntu-中安裝-obs" aria-label="Permalink to “1、在 Ubuntu 中安裝 OBS”">​</a></h4><p>OBS（Open Broadcaster Software）是眾多用於錄製和直播視頻的優秀軟件之一，許多直播者都選擇使用 OBS 在各個數字化平台進行直播。</p><p>幸運的是，OBS 已經包含在 Ubuntu 的默認倉庫中，你可以通過以下命令來安裝：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install obs-studio</span></span></code></pre></div><h4 id="_2、通過-vdo-ninja-生成直播邀請" tabindex="-1">2、通過 VDO.ninja 生成直播邀請 <a class="header-anchor" href="#_2、通過-vdo-ninja-生成直播邀請" aria-label="Permalink to “2、通過 VDO.ninja 生成直播邀請”">​</a></h4><p>在這一節，我將教你如何在 vdo.ninja 上生成一個直播邀請，進而從你的手機上開始直播音頻和視頻。</p>',10)),i("p",null,[t[4]||(t[4]=n("首先，訪問 ",-1)),o(s,{href:"https://vdo.ninja/"},{default:r(()=>[...t[3]||(t[3]=[n("VDO.ninja",-1)])]),_:1}),t[5]||(t[5]=n(" 並點擊 “",-1)),t[6]||(t[6]=i("ruby",null,[n("創建可重用的邀請"),i("rt",null,"Create Reusable Invite")],-1)),t[7]||(t[7]=n("”：",-1))]),t[35]||(t[35]=a('<p><img src="https://itsfoss.com/content/images/2023/08/Click-on-create-reusable-Invite-button.png" alt=""></p><p>接下來你會看到很多選項，包括質量設置，添加視頻效果等。我推薦你使用默認設置，因為高質量視頻需要更快的處理速度和更多的帶寬。</p><p>為了創建一個鏈接，你只需要點擊 “<ruby>生成邀請鏈接<rt>GENERATE THE INVITE LINK</rt></ruby>” 按鈕：</p><p><img src="https://itsfoss.com/content/images/2023/08/Click-on-the-generate-invite-link-button.png" alt=""></p><p>完成後你會看到：</p><ul><li>你需要用你的手機掃描的二維碼（當然，你也可以選擇使用鏈接）。</li><li>OBS 的鏈接。</li></ul><p><strong>稍後我會在本教程中繼續介紹 OBS 配置，所以請暫時別關閉這個窗口。</strong></p><p>首先，用你的手機掃描二維碼，它會將你跳轉到 VDO.ninja 的另一個頁面，此時你需要：</p><ul><li>選擇 “<ruby>共享你的相機<rt>Share your Camera</rt></ruby>” 選項。</li><li>在視頻源中選擇使用前置或後置攝像頭（默認為前置）。</li><li>點擊 “<ruby>開始<rt>Start</rt></ruby>” 按鈕後，它將開始在 OBS 連接的頁面上進行直播。</li></ul><p><img src="https://itsfoss.com/content/images/2023/08/setup-vdo.ninja-on-phone.png" alt=""></p><h4 id="_3、在-ubuntu-上為-obs-配置虛擬線纜" tabindex="-1">3、在 Ubuntu 上為 OBS 配置虛擬線纜 <a class="header-anchor" href="#_3、在-ubuntu-上為-obs-配置虛擬線纜" aria-label="Permalink to “3、在 Ubuntu 上為 OBS 配置虛擬線纜”">​</a></h4><blockquote><p>🚧 這種設置方法僅適用於 PulseAudio，並且在重啓系統後虛擬線纜將被撤銷。</p></blockquote><p>首先，我們來解釋一下“<ruby>虛擬線纜<rt>virtual cable</rt></ruby>”的概念，以及為何我們需要它來將手機做為攝像頭和麥克風使用。</p><p>虛擬線纜是一種用於將音頻流從一個應用傳輸到另一個應用的軟件。</p><p>然而遺憾的是，它只支持 Windows 和 macOS。</p><p>啥？！那我為什麼還要介紹這個呢？</p><p>答案其實很簡單。我找到了一種變通方法，你可以在<strong>當前的會話</strong>中獲得與虛擬線纜類似的功能。</p><p>要設置虛擬線纜，首先需要使用以下命令加載 <code>module-null-sink</code> 模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pactl load-module module-null-sink sink_name=Source</span></span></code></pre></div><p>然後，執行下面的命令創建一個名為 <code>VirtualMic</code> 的虛擬音源：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pactl load-module module-virtual-source source_name=VirtualMic master=Source.monitor</span></span></code></pre></div><p>這兩個命令將返回一些數字，但無需對其過多關注。</p><p>接下來，前往系統“<ruby>設置<rt>Settings</rt></ruby>”，找到“<ruby>聲音<rt>Sound</rt></ruby>”部分的設置：</p><p><img src="https://itsfoss.com/content/images/2023/08/Open-sound-settings.png" alt=""></p><p>然後進入 “<ruby>輸入<rt>Input</rt></ruby>” 部分，在此你會找到選擇輸入設備的選項。</p><p>將 “VirtualMic” 設為輸入設備：</p><p><img src="https://itsfoss.com/content/images/2023/08/Choose-virtul-mic-as-an-audio-input-in-Linux-to-use-phone-s-camera-and-mic-.png" alt=""></p><p>這樣就設置完了！</p><p>不過，如我之前所述，一旦你重啓電腦，虛擬音頻的設置就會被撤銷，如果你打算經常使用手機作為攝像頭和麥克風，這可能會造成一定的不便。</p>',29)),i("p",null,[t[9]||(t[9]=n("為了解決這個問題，你可以為這兩個命令 ",-1)),o(s,{href:"https://linuxhandbook.com/linux-alias-command/"},{default:r(()=>[...t[8]||(t[8]=[n("創建別名",-1)])]),_:1}),t[10]||(t[10]=n("，例如，為命令創建別名：",-1)),t[11]||(t[11]=i("code",null,"vc1",-1)),t[12]||(t[12]=n(" 和 ",-1)),t[13]||(t[13]=i("code",null,"vc2",-1)),t[14]||(t[14]=n("。",-1))]),i("p",null,[t[16]||(t[16]=n("完成後，你就可以像這樣 ",-1)),o(s,{href:"https://linuxhandbook.com/run-multiple-commands/"},{default:r(()=>[...t[15]||(t[15]=[n("一次執行兩個命令",-1)])]),_:1}),t[17]||(t[17]=n("：",-1)),t[18]||(t[18]=i("code",null,"vc1 && vc2",-1)),t[19]||(t[19]=n("。",-1))]),t[36]||(t[36]=a('<h4 id="_4、配置-obs-從手機直播音視頻" tabindex="-1">4、配置 OBS 從手機直播音視頻 <a class="header-anchor" href="#_4、配置-obs-從手機直播音視頻" aria-label="Permalink to “4、配置 OBS 從手機直播音視頻”">​</a></h4><p>開始階段，你需要打開我之前告訴你不要關閉的 VDO.ninja 標籤頁，並複製 OBS 鏈接：</p><p><img src="https://itsfoss.com/content/images/2023/08/Copy-link-for-OBS.png" alt=""></p><p>然後啓動 OBS，在 “<ruby>源<rt>Sources</rt></ruby>” 區域你會看到一個 “➕（加號）”按鈕，點擊這個按鈕並選擇 “<ruby>瀏覽<rt>Browser</rt></ruby>”。</p><p>接着會彈出一個對話框，讓你創建或選擇一個源，你只需按下 “OK” 按鈕即可：</p><p><img src="https://itsfoss.com/content/images/2023/08/Create-new-source-for-streaming-in-OBS-to-use-camera-and-mic-of-your-phone-in-Ubuntu-1.png" alt=""></p><p>最後，將已經複製的鏈接粘貼進 “URL” 字段：</p><p><img src="https://itsfoss.com/content/images/2023/08/Paste-VDO.ninja-link-in-OBS-to-use-your-phone-s-camera-and-mic-in-Ubuntu-Linux.png" alt=""></p><p>然後你將能看到 OBS 正在使用你手機的攝像頭：</p><p><img src="https://itsfoss.com/content/images/2023/08/Stream-audio-and-video-from-your-phone-to-Ubuntu-Linux-using-OBS.png" alt=""></p><p>不過為了從你的手機接收音頻，還有一些額外步驟需要執行。</p><p>首先，在菜單中點擊 “<ruby>文件<rt>File</rt></ruby>” 並選擇 “<ruby>設置<rt>Settings</rt></ruby>”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Open-settings-in-OBS.png" alt=""></p><p>在出現的設置選項中選擇 “<ruby>音頻<rt>Audio</rt></ruby>”，然後尋找到 “<ruby>高級<rt>Advanced</rt></ruby>” 區域。</p><p>在 “高級” 區域裏，你能找到 “<ruby>監控設備<rt>Monitoring Device</rt></ruby>” 的選項，這裏你需要選擇 “Source Audio/Sink sink”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Choose-virtual-audio-in-OBS-to-use-phone-s-mic-in-ubuntu-Linux.png" alt=""></p><p>點擊 “<ruby>應用<rt>Apply</rt></ruby>” 保存更改。</p><p>對於大部分用户，此時音頻應該已經能夠正常工作了。如果你的音頻依然無法工作，那麼你可以按照以下步驟操作。</p><p>在 “<ruby>音頻混音器<rt>Audio Mixer</rt></ruby>” 區域，可能顯示的是 “<ruby>瀏覽<rt>Browser</rt></ruby>” 或 “<ruby>桌面音頻<rt>Desktop Audio</rt></ruby>”，也可能兩者都顯示。</p><p>點擊 “桌面音頻” 或 “瀏覽” 旁邊的三個點（在我這個例子中，是 “桌面音頻”），並選擇 “<ruby>高級音頻屬性<rt>Advanced Audio Properties</rt></ruby>”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Choose-advanced-option-to-use-audio-from-phone-in-Ubuntu-linux-using-OBS.png" alt=""></p><p>然後，對於 “瀏覽” 和 “桌面音頻”，都選擇 “<ruby>監控和輸出<rt>Monitor and Output</rt></ruby>”：</p><p><img src="https://itsfoss.com/content/images/2023/08/Enable-monitor-and-output-for-OBS.png" alt=""></p><p>這樣就可以了！現在你可以從你的手機上享受攝像頭和麥克風的功能了。</p><h4 id="_5、測試所有設置" tabindex="-1">5、測試所有設置 <a class="header-anchor" href="#_5、測試所有設置" aria-label="Permalink to “5、測試所有設置”">​</a></h4><p>為了測試這個設置，我在我們讀書俱樂部的週會上用我的手機做為攝像頭和麥克風，效果極佳。</p><p><img src="https://itsfoss.com/content/images/2023/08/Using-phone-s-camera-and-mic-in-Ubuntu-Linux.png" alt=""></p><p>你可以看到，上圖顯示攝像頭和麥克風都在正常工作，這真的讓我笑容滿面 😸。</p><p>視頻質量會取決於你的網絡帶寬，所以在開始重要的會議前，確保你有穩定的網絡連接。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>作為一個沒有攝像頭和麥克風的台式計算機用户，我必須依靠筆記本或手機來參加工作會議，這讓我感到非常煩躁。</p><p>需要注意的是，每次重啓機器後，你都需要重新配置虛擬線纜，但這並不費時，因為只需要執行兩條命令即可。</p><p>我已經多次使用這種解決方案，每一次都順利運行。我真的希望你也能得到同樣的結果。</p><p><em>（題圖：MJ/223b56b7-ffcc-4311-bfa6-8a25bfd5ad11）</em></p><hr>',35)),i("p",null,[t[21]||(t[21]=n("via: ",-1)),o(s,{href:"https://itsfoss.com/ubuntu-phone-camera-mic/"},{default:r(()=>[...t[20]||(t[20]=[n("https://itsfoss.com/ubuntu-phone-camera-mic/",-1)])]),_:1})]),i("p",null,[t[25]||(t[25]=n("作者：",-1)),o(s,{href:"https://itsfoss.com/author/sagar/"},{default:r(()=>[...t[22]||(t[22]=[n("Sagar Sharma",-1)])]),_:1}),t[26]||(t[26]=n(" 選題：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[23]||(t[23]=[n("lujun9972",-1)])]),_:1}),t[27]||(t[27]=n(" 譯者：ChatGPT 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[24]||(t[24]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[30]||(t[30]=n("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[28]||(t[28]=[n("LCTT",-1)])]),_:1}),t[31]||(t[31]=n(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:r(()=>[...t[29]||(t[29]=[n("Linux中國",-1)])]),_:1}),t[32]||(t[32]=n(" 榮譽推出",-1))])])}const T=u(d,[["render",b]]);export{x as __pageData,T as default};
